-- =====================================================================
--  Revnu v2 — seed for the new catalogues (generated from the client's v2
--  prototype data by gen-v2-seed.mjs). Never overwrites live data:
--    · catalogue rows: insert ... on conflict do nothing
--    · project / developer: new keys merged in, existing values win
--    · Arabic text: diacritics stripped in place (the client's prototype
--      normalised every Arabic string this way), so UAT edits survive
-- =====================================================================
begin;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

update public.projects set
  features          = '{"furnishing":true,"smartHome":true,"operations":true,"fitout":false,"kitchens":false,"cooling":false,"flooring":true,"layout":true}'::jsonb || features,
  optional          = '{"smartHome":true,"operations":true,"kitchens":true,"cooling":true,"flooring":true,"layout":true}'::jsonb || optional,
  layout_deadline   = coalesce(layout_deadline, '2027-01-31'::date),
  flooring_deadline = coalesce(flooring_deadline, '2027-04-30'::date),
  layout_rates      = coalesce(layout_rates, '{"wallPerM":950,"doorPrice":1800}'::jsonb),
  total_units       = case when total_units = 373 then 3000 else total_units end
where id = 'nk-noor-khuzam';

update public.developers set
  plan      = coalesce(plan, '{"onboarding":{"mode":"waived","reason":"Pilot partner — onboarding waived"},"projectSetup":{"mode":"waived","reason":"Pilot partner — setup waived"},"annual":{"mode":"waived","waiveYears":1,"reason":"Pilot partner — first-year platform fee waived"}}'::jsonb),
  signature = coalesce(signature, '/brand/noor-khuzam-signature.png'),
  stamp     = coalesce(stamp, '/brand/noor-khuzam-stamp.png')
where id = 'noor-khuzam';

update public.design_styles set name_ar = regexp_replace(name_ar, '[\u064B-\u065F\u0670]', '', 'g'), mood_ar = regexp_replace(mood_ar, '[\u064B-\u065F\u0670]', '', 'g'), palette_note_ar = regexp_replace(palette_note_ar, '[\u064B-\u065F\u0670]', '', 'g'), palettes = case when palettes is null then null else regexp_replace(palettes::text, '[\u064B-\u065F\u0670]', '', 'g')::jsonb end, images = case when images is null then null else regexp_replace(images::text, '[\u064B-\u065F\u0670]', '', 'g')::jsonb end, materials_ar = (select coalesce(array_agg(regexp_replace(x, '[\u064B-\u065F\u0670]', '', 'g') order by ord), '{}') from unnest(materials_ar) with ordinality t(x, ord));
update public.packages      set name_ar = regexp_replace(name_ar, '[\u064B-\u065F\u0670]', '', 'g'), tier_ar = regexp_replace(tier_ar, '[\u064B-\u065F\u0670]', '', 'g'), summary_ar = regexp_replace(summary_ar, '[\u064B-\u065F\u0670]', '', 'g'), boq = case when boq is null then null else regexp_replace(boq::text, '[\u064B-\u065F\u0670]', '', 'g')::jsonb end, boq_by_type = case when boq_by_type is null then null else regexp_replace(boq_by_type::text, '[\u064B-\u065F\u0670]', '', 'g')::jsonb end, fitout = case when fitout is null then null else regexp_replace(fitout::text, '[\u064B-\u065F\u0670]', '', 'g')::jsonb end;
update public.smart_home    set name_ar = regexp_replace(name_ar, '[\u064B-\u065F\u0670]', '', 'g'), summary_ar = regexp_replace(summary_ar, '[\u064B-\u065F\u0670]', '', 'g'), includes_ar = (select coalesce(array_agg(regexp_replace(x, '[\u064B-\u065F\u0670]', '', 'g') order by ord), '{}') from unnest(includes_ar) with ordinality t(x, ord));
update public.ops_models    set name_ar = regexp_replace(name_ar, '[\u064B-\u065F\u0670]', '', 'g'), summary_ar = regexp_replace(summary_ar, '[\u064B-\u065F\u0670]', '', 'g');
update public.unit_types    set name_ar = regexp_replace(name_ar, '[\u064B-\u065F\u0670]', '', 'g'), level_names_ar = (select coalesce(array_agg(regexp_replace(x, '[\u064B-\u065F\u0670]', '', 'g') order by ord), '{}') from unnest(level_names_ar) with ordinality t(x, ord));
update public.projects      set name_ar = regexp_replace(name_ar, '[\u064B-\u065F\u0670]', '', 'g'), city_ar = regexp_replace(city_ar, '[\u064B-\u065F\u0670]', '', 'g'), tagline_ar = regexp_replace(tagline_ar, '[\u064B-\u065F\u0670]', '', 'g');
update public.developers    set name_ar = regexp_replace(name_ar, '[\u064B-\u065F\u0670]', '', 'g'), legal_name_ar = regexp_replace(legal_name_ar, '[\u064B-\u065F\u0670]', '', 'g'), authorized_signer_ar = regexp_replace(authorized_signer_ar, '[\u064B-\u065F\u0670]', '', 'g'), authorized_signer_title_ar = regexp_replace(authorized_signer_title_ar, '[\u064B-\u065F\u0670]', '', 'g'), tagline_ar = regexp_replace(tagline_ar, '[\u064B-\u065F\u0670]', '', 'g');
update public.dev_roles     set ar = regexp_replace(ar, '[\u064B-\u065F\u0670]', '', 'g');
update public.revnu_roles   set ar = regexp_replace(ar, '[\u064B-\u065F\u0670]', '', 'g');
update public.dev_perms     set ar = regexp_replace(ar, '[\u064B-\u065F\u0670]', '', 'g');
update public.revnu_perms   set ar = regexp_replace(ar, '[\u064B-\u065F\u0670]', '', 'g');

commit;
