  ('nk-kit-loft', 'nk-noor-khuzam', 'Loft Dark', 'لوفت داكن', 'Handle-less dark fronts, black stone worktop and an open shelving run with warm lighting.', 'واجهات داكنة بدون مقابض وسطح حجري أسود ورفوف مفتوحة بإضاءة دافئة.', '[{"id":"k1","label":"Open kitchen & living · view 1","labelAr":"المطبخ المفتوح والمعيشة · منظر ١","src":"/images/noor/wc-1.jpg"},{"id":"k2","label":"Open kitchen & living · view 2","labelAr":"المطبخ المفتوح والمعيشة · منظر ٢","src":"/images/noor/wc-2.jpg"}]'::jsonb, '[{"id":"graphite","name":"Graphite & Walnut","nameAr":"غرافيت وجوزي","colors":["#3A3A3C","#7B5A3E","#1C1C1E","#D9D4CA"]},{"id":"forest","name":"Forest & Black","nameAr":"أخضر غامق وأسود","colors":["#2E4A3F","#1C1C1E","#C7BFAE","#8A8378"]},{"id":"terra","name":"Terracotta & Ash","nameAr":"تراكوتا ورمادي","colors":["#B5654A","#4A4A4A","#E6DED2","#1C1C1E"]}]'::jsonb, '{"cabinets":{"includes":["Handle-less base & wall units · push-open","Deep drawer bank","Black stone worktop · 20 mm","Undermount sink + black tap","Open shelving with LED strip"],"includesAr":["وحدات بدون مقابض · فتح بالضغط","مجموعة أدراج عميقة","سطح حجري أسود · 20 مم","حوض مدمج وخلاط أسود","رفوف مفتوحة بشريط إضاءة"],"pricing":{"NK-S":21500,"NK-M":27500,"NK-L":34500,"NK-TH":40000,"NK-PH":43000}},"full":{"includes":["Everything in cabinets","Fridge-freezer · integrated","Built-in oven + combi-steam","Induction hob + downdraft hood","Dishwasher · integrated"],"includesAr":["كل ما في الخزائن","ثلاجة وفريزر · مدمجة","فرن مدمج وفرن بخار","موقد حثي وشفاط سطحي","غسالة صحون · مدمجة"],"pricing":{"NK-S":33000,"NK-M":41000,"NK-L":49500,"NK-TH":56000,"NK-PH":59500}}}'::jsonb, '[{"id":"washerdryer","name":"Washer-dryer · utility niche","nameAr":"غسالة ومجفف · ركن الخدمة","price":4500,"scopes":["full"]},{"id":"filter","name":"Under-sink water filter","nameAr":"فلتر ماء تحت الحوض","price":950,"scopes":["cabinets","full"]},{"id":"led","name":"Extra LED shelf lighting run","nameAr":"شريط إضاءة إضافي للرفوف","price":1200,"scopes":["cabine